import { createSignal } from 'solid-js';
import { prefGet, prefSet } from '../model/prefs.js';
import { view } from './view.js';

export function corpusKey(): string {
  const sources = [...view.src, ...view.ttl, ...(view.sparql ? [view.sparql] : [])];
  return 'open:' + [...sources].sort().join('|');
}

const [stateVersion, setStateVersion] = createSignal(0);
let stateKey: string | null = null;
let state: Set<string> | null = null;

// READ MIGRATIONS: folds were stored under Dutch prefixes before the rename —
// forms under `vorm:` and grouping rows under `groep:`. This is persistent user
// state in localStorage, so a reader that does not recognise the old prefix
// silently forgets which folds were open. The translation happens on read; the
// next write stores the new prefix only. The legacy strings are a RECORD of
// what was written and must not be rewritten.
const LEGACY_PREFIXES: [string, string][] = [['vorm:', 'form:'], ['groep:', 'group:']];

function migrateKey(k: string): string {
  for (const [old, fresh] of LEGACY_PREFIXES) {
    if (k.startsWith(old)) return fresh + k.slice(old.length);
  }
  return k;
}

function stateFor(key: string): Set<string> {
  if (state === null || stateKey !== key) {
    const saved = prefGet(key, []);
    state = new Set<string>(Array.isArray(saved) ? saved.map(migrateKey) : []);
    stateKey = key;
  }
  return state;
}

export function forgetOpenState(): void {
  state = null;
  stateKey = null;
  rowState.clear();
  rowStateKey = null;
  setStateVersion((v) => v + 1);
  setRowVersion((v) => v + 1);
}

const rowState = new Map<string, boolean>();
const [rowVersion, setRowVersion] = createSignal(0);
let rowStateKey: string | null = null;

function rowStateFor(): Map<string, boolean> {
  const corpus = corpusKey();
  if (rowStateKey !== corpus) {
    rowState.clear();
    rowStateKey = corpus;
  }
  return rowState;
}

export function volatileState(key: string): boolean | null {
  if (!key) return null;
  rowVersion();
  const v = rowStateFor().get(key);
  return v === undefined ? null : v;
}

export function isRowOpen(key: string): boolean {
  return volatileState(key) === true;
}

export function setRowOpen(key: string, open: boolean): void {
  if (!key) return;
  const s = rowStateFor();
  if (s.get(key) === open) return;
  s.set(key, open);
  setRowVersion((v) => v + 1);
}

export function isOpen(key: string): boolean {
  stateVersion();
  if (!key) return false;
  return stateFor(corpusKey()).has(key);
}

// A blank->named promotion gives the node a new address, and a card keyed by
// the old one would fold shut under the author's hands. The keys move with it:
// the card's own key, and every row/group/form key scoped to it (those carry
// the address after a `:` or a `|`).
export function moveOpenKey(from: string, to: string): void {
  if (!from || !to || from === to) return;
  const corpus = corpusKey();
  const s = stateFor(corpus);
  // A key is `<prefix>:<address>` with further parts after `|` or `>`, so the
  // address is only replaced where it fills a whole part — `edit-1` must not
  // eat the `edit-1` inside `edit-11`.
  const SEP = /[:|>]/;
  const swap = (k: string): string | null => {
    if (k === from) return to;
    const i = k.indexOf(from);
    if (i < 1 || !SEP.test(k[i - 1])) return null;
    const after = k[i + from.length];
    if (after !== undefined && !SEP.test(after)) return null;
    return k.slice(0, i) + to + k.slice(i + from.length);
  };
  let changed = false;
  for (const k of [...s]) {
    const fresh = swap(k);
    if (!fresh) continue;
    s.delete(k); s.add(fresh); changed = true;
  }
  for (const [k, v] of [...rowStateFor()]) {
    const fresh = swap(k);
    if (!fresh) continue;
    rowState.delete(k); rowState.set(fresh, v); changed = true;
  }
  if (!changed) return;
  prefSet(corpus, [...s]);
  setStateVersion((v) => v + 1);
  setRowVersion((v) => v + 1);
}

// Bookkeeping, not a snapshot of the DOM: on a rerender most of it is not drawn,
// so every toggle updates only its own key.
export function setOpen(key: string, open: boolean): void {
  if (!key) return;
  const corpus = corpusKey();
  const s = stateFor(corpus);
  const was = s.has(key);
  if (open) s.add(key); else s.delete(key);
  if (s.has(key) === was) return;
  prefSet(corpus, [...s]);
  setStateVersion((v) => v + 1);
}
