import { createSignal, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { text } from '../../stores/view.js';

export const LONG_TEXT_LIMIT = 600;

export function truncated(value: string): string {
  return value.slice(0, LONG_TEXT_LIMIT).trimEnd() + '…';
}

export function LongText(props: { text?: string | null }): JSX.Element {
  const [open, setOpen] = createSignal(false);
  const s = () => String(props.text ?? '');
  const long = () => s().length > LONG_TEXT_LIMIT;
  return (
    <Show when={long()} fallback={<span>{s()}</span>}>
      <span class="longtext">
        <span>{open() ? s() : truncated(s())}</span>
        {' '}
        <button
          type="button" class="toggle-more"
          aria-expanded={open() ? 'true' : 'false'}
          onClick={() => setOpen((v) => !v)}
        >
          {open() ? text('text.showLess') : text('text.showMore', { n: s().length })}
        </button>
      </span>
    </Show>
  );
}
