export const SCROLL_SYNC_MARGIN = 12;

const OPEN_GESTURE_MS = 500;

export interface ScrollSyncMetrics {
  top: number;
  bottom: number;
  scrollY?: number;
  viewportHeight?: number;
  headerOffset?: number;
  margin?: number;
}

export function scrollSyncTarget({
  top, bottom, scrollY = 0, viewportHeight = 0,
  headerOffset = 0, margin = SCROLL_SYNC_MARGIN,
}: ScrollSyncMetrics): number | null {
  if (!viewportHeight || bottom <= viewportHeight) return null;
  const wantTop = scrollY + top - headerOffset - margin;
  const wantBottom = scrollY + (bottom - viewportHeight);
  const target = Math.max(0, Math.min(wantTop, wantBottom));
  return Math.abs(target - scrollY) < 2 ? null : target;
}

let lastGesture: { el: Element; t: number } | null = null;

export function rememberOpenGesture(el: Element | null | undefined): void {
  lastGesture = el ? { el, t: Date.now() } : null;
}

export function forgetOpenGesture(): void {
  lastGesture = null;
}

function topbarOffset(): number {
  if (typeof document === 'undefined' || !document.querySelector) return 0;

  const bar = document.querySelector('.app-header, .app-topbar, .doc-topbar');
  if (!bar || !bar.getBoundingClientRect) return 0;
  const pos = typeof getComputedStyle === 'function' ? getComputedStyle(bar).position : '';
  if (pos !== 'sticky' && pos !== 'fixed') return 0;
  const r = bar.getBoundingClientRect();
  return r.bottom > 0 ? r.bottom : 0;
}

// Duplicated from fill.tsx on purpose: importing it would pull the fill panel
// into the read chunk.
function mayAnimate(): boolean {
  return !(typeof window !== 'undefined' && typeof window.matchMedia === 'function'
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

function applyScrollSync(el: HTMLElement): void {
  const r = el.getBoundingClientRect();
  const target = scrollSyncTarget({
    top: r.top,
    bottom: r.bottom,
    scrollY: window.scrollY || 0,
    viewportHeight: window.innerHeight || 0,
    headerOffset: topbarOffset(),
  });
  if (target == null) return;

  const smooth = mayAnimate();
  try {
    window.scrollTo({ top: target, left: window.scrollX || 0, behavior: smooth ? 'smooth' : 'auto' });
  } catch {
    window.scrollTo(0, target);
  }
}

function scheduleScrollSync(el: HTMLElement): void {
  if (typeof window === 'undefined' || !window.scrollTo || !el.getBoundingClientRect) return;
  const raf = typeof requestAnimationFrame === 'function'
    ? requestAnimationFrame : (fn: FrameRequestCallback) => setTimeout(fn, 16);
  let previous = -1;
  let attempts = 0;
  const step = () => {
    const height = el.getBoundingClientRect().height;
    const loading = el.querySelector && el.querySelector('.card-loading');
    if ((height !== previous || loading) && attempts < 60) {
      previous = height;
      attempts += 1;
      raf(step);
      return;
    }
    applyScrollSync(el);
  };
  raf(step);
}

export function scrollSyncAfterExpand(el: HTMLElement): void {
  const g = lastGesture;
  if (!g || g.el !== el || Date.now() - g.t > OPEN_GESTURE_MS) return;
  lastGesture = null;
  scheduleScrollSync(el);
}
