// `new URL` and not a regex: relative addresses must keep working, and
// `javascript:alert(1)` looks like a relative path with a colon in it.
export function safeHref(
  address: string | null | undefined, base?: string,
): string | null {
  const s = String(address ?? '').trim();
  if (!s) return null;
  const ground = base
    ?? (typeof location !== 'undefined' && location.href ? location.href : 'https://x.invalid/');
  try {
    const u = new URL(s, ground);
    return u.protocol === 'http:' || u.protocol === 'https:' ? s : null;
  } catch {
    return null;
  }
}

export function safeLink(address: string | null | undefined, base?: string): boolean {
  return safeHref(address, base) !== null;
}
